// my brush rect

function mBrect(x, y, w, h, c = "black") {
	push();
	noStroke();
	fill(BG);
	// rect(x, y, w, h);

	beginClip();
	// rect(x, y, w, h);
	for (yy = y; yy < y + h; yy++) rect(x + random(5), yy, w, 1)
	endClip();

	const eas = getRandomEasing();
	// console.log(eas(0.5))

	const clr = typeof c === "string" ? color(c) : typeof c === "number" ? color(c) : c;
	for (yy = y; yy < y + h; yy++) {
		clr.setAlpha(48);
		stroke(clr);
		line(x, yy, x + abs(randomGaussian(w*eas(1), w/3)), yy);

		clr.setAlpha(96);
		stroke(clr);
		line(x, yy, x + abs(randomGaussian(w*eas(2/3), w/6)), yy);

		clr.setAlpha(192);
		stroke(clr);
		line(x, yy, x + abs(randomGaussian(w*eas(1/3), w/9)), yy);

		clr.setAlpha(255);
		stroke(clr);
		line(x, yy, x + abs(randomGaussian(w*eas(1/3), w/9)), yy);
		line(x, yy, x + abs(randomGaussian(w*eas(1/3), w/9)), yy);
	}

	pop();
}

function getRandomEasing() {
	return random([
		Easings.easeInQuad,
		Easings.easeOutQuad,
		Easings.easeInOutQuad,
		Easings.easeInCubic,
		Easings.easeOutCubic,
		Easings.easeInOutCubic,
		Easings.easeInSine,
	]);
}

// === Tab: easings ===
class Easings {


easeInQuad(x) {
	return x * x;
}
easeOutQuad(x) {
	return 1 - ( 1 - x ) * ( 1 - x );
}
easeInOutQuad(x) {
	return x < 0.5 ?
		2 * x * x :
		1 - pow( -2 * x + 2, 2 ) / 2;
}
easeInCubic(x) {
	return x * x * x;
}
easeOutCubic(x) {
	return 1 - pow( 1 - x, 3 );
}
easeInOutCubic(x) {
	return x < 0.5 ?
		4 * x * x * x :
		1 - pow( -2 * x + 2, 3 ) / 2;
}
easeInQuart(x) {
	return x * x * x * x;
}
easeOutQuart(x) {
	return 1 - pow( 1 - x, 4 );
}
easeInOutQuart(x) {
	return x < 0.5 ?
		8 * x * x * x * x :
		1 - pow( -2 * x + 2, 4 ) / 2;
}
easeInQuint(x) {
	return x * x * x * x * x;
}
easeOutQuint(x) {
	return 1 - pow( 1 - x, 5 );
}
easeInOutQuint(x) {
	return x < 0.5 ?
		16 * x * x * x * x * x :
		1 - pow( -2 * x + 2, 5 ) / 2;
}
easeInSine(x) {
	return 1 - cos( x * PI/2 );
}
easeOutSine(x) {
	return sin( x * PI/2 );
}
easeInOutSine(x) {
	return -( cos( PI * x ) - 1 ) / 2;
}
easeInExpo(x) {
	return x === 0 ? 0 : pow( 2, 10 * x - 10 );
}
easeOutExpo(x) {
	return x === 1 ? 1 : 1 - pow( 2, -10 * x );
}
easeInOutExpo(x) {
	return x === 0 ? 0 : x === 1 ? 1 : x < 0.5 ?
		pow( 2, 20 * x - 10 ) / 2 :
		( 2 - pow( 2, -20 * x + 10 ) ) / 2;
}
easeInCirc(x) {
	return 1 - sqrt( 1 - pow( x, 2 ) );
}
easeOutCirc(x) {
	return sqrt( 1 - pow( x - 1, 2 ) );
}
easeInOutCirc(x) {
	return x < 0.5 ?
		( 1 - sqrt( 1 - pow( 2 * x, 2 ) ) ) / 2 :
		( sqrt( 1 - pow( -2 * x + 2, 2 ) ) + 1 ) / 2;
}
easeInElastic(x) {
	return x === 0 ? 0 : x === 1 ? 1 :
		-pow( 2, 10 * x - 10 ) * sin( ( x * 10 - 10.75 ) * c4 );
}
easeOutElastic(x) {
	return x === 0 ? 0 : x === 1 ? 1 :
		pow( 2, -10 * x ) * sin( ( x * 10 - 0.75 ) * c4 ) + 1;
}
easeInOutElastic(x) {
	return x === 0 ? 0 : x === 1 ? 1 : x < 0.5 ?
		-( pow( 2, 20 * x - 10 ) * sin( ( 20 * x - 11.125 ) * c5 )) / 2 :
		pow( 2, -20 * x + 10 ) * sin( ( 20 * x - 11.125 ) * c5 ) / 2 + 1;
}
easeInBack(x) {
	return c3 * x * x * x - c1 * x * x;
}
easeOutBack(x) {
	return 1 + c3 * pow( x - 1, 3 ) + c1 * pow( x - 1, 2 );
}
easeInOutBack(x) {
	return x < 0.5 ?
		( pow( 2 * x, 2 ) * ( ( c2 + 1 ) * 2 * x - c2 ) ) / 2 :
		( pow( 2 * x - 2, 2 ) *( ( c2 + 1 ) * ( x * 2 - 2 ) + c2 ) + 2 ) / 2;
}
easeInBounce(x) {
	return 1 - bounceOut( 1 - x );
}

easeOutBounce(x) {
    return bounceOut(x);
}
easeInOutBounce(x) {
	return x < 0.5 ?
		( 1 - bounceOut( 1 - 2 * x ) ) / 2 :
		( 1 + bounceOut( 2 * x - 1 ) ) / 2;
}

}

// === Tab: mySketch ===
// inspired by https://www.borislafleur.com/

var MAR = 25;
var BG = "#F1D9BA";
var x, y, w, h;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(30);
	init();
}

function init() {
	loop();
	background(BG);
	x = -width; // MAR
	y = MAR;
	h = getH();
	w = getW();
}

function getW() {
	return ~~(random(0.2, 0.7) * width);
}
function getH() {
	return ~~(random(0.05, 0.3) * height);	
}

function mousePressed() {
	init();
}

function draw() {

	mBrect(x, y, min(w, width-MAR-x), min(h, height-MAR-y));
	x += w;
	if (x > width - MAR) {
		x = -width; // MAR
		y += h;
		h = getH();
	}
	w = getW();

	if (y > height - MAR) {
		// noLoop() removed for animation
		if (random() < 0.5) 
		for (i = 0; i < 19; i++) {
			const xx = random(-0.2, 0.8) * width;
			const yy = random(-0.2, 0.8) * height;
			const ww = getW();
			const hh = getH(); 
			mBrect(xx, yy, min(ww, width-MAR-xx), min(hh, height-MAR-yy), random(["darkred", "navy", "black", "black"]));
		}
	}

	/*
	for (y = 0, h = 1; y < height; y += h) {
		h = random(0.1, 0.3) * height;	
		for (x = 0, w = 1; x < width*0.9; x += w) {
			w = random(0.3, 0.7) * width;
			rect(x, y, w, h);
		}
	}
	*/

	noStroke();
	fill(BG);
	rect(0, 0, MAR, height);
	rect(0, 0, width, MAR);
}
